Q: Cycles in small directed graph A: <p>You can just follow the path starting from a node, and mark each node you visit like that as visited. When you encounter a visited node, you have a cycle, which starts at that revisited node. Then do the same for the next unvisited node until all are visited.</p>
<p>The data structure for representing such a graph could be an array, where the index (0, 1, ..., 4) identifies the node, and the value at that index identifies the neighbor to which the directed edge from that node goes.</p>
<p>Here is a simple implementation in JavaScript:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function collectCycles(graph) {
    const cycles = [];
    const visited = Array(graph.length).fill(false);
    for (let node = 0; node &lt; graph.length; node++) {
        const cycle = [];
        while (!visited[node]) {
            visited[node] = true;
            cycle.push(node);
            node = graph[node]; // go to (only) neighbor
        }
        const i = cycle.indexOf(node);
        if (i &gt;= 0) {
            cycle.splice(0, i); // Remove the path leading to the cycle
            cycles.push(cycle);
        }
    }
    return cycles;
}

// Examples
const graphs = [
    [4, 2, 1, 3, 0],
    [1, 2, 1, 0, 4]
];
for (const graph of graphs) {
    const cycles = collectCycles(graph);
    console.log(`graph ${JSON.stringify(graph)} has cycles ${JSON.stringify(cycles)}`);
}</code></pre>
